def sin_gate6gc(rel: str, txt: str) -> str:
    # Actualizado en Gate 6G-D: primero se deshacen EXACTAMENTE sus cambios
    from _base_gate6gd import sin_gate6gd
    txt = sin_gate6gd(rel, txt)
    for clave, bl in _BLOQUES.items():
        if rel.replace("\\", "/").endswith(clave):
            if not all(txt.count(nuevo) == 1 for nuevo, _ in bl):
                return txt
            for nuevo, viejo in bl:
                txt = txt.replace(nuevo, viejo, 1)
            return txt
    return txt
